head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf90600";
scwin.comment = null;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.comment = $c.util.getComponent('comment');
        await scwin.init_rowCopy();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf90600.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_itemId", fn: function () { return String((dma_pageContext.get("itemId") ?? "")); } },
        { childId: "ipt_itemNm", fn: function () { return String((dma_pageContext.get("itemNm") ?? "")); } },
        { childId: "ipt_searchType", fn: function () { return String((dma_pageContext.get("searchType") ?? "")); } },
        { childId: "ipt_searchWord", fn: function () { return String((dma_pageContext.get("searchWord") ?? "")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $c.util.getComponent("ipt_searchWord").focus();
        $c.util.getComponent('ipt_searchWord').setValue(($c.util.getComponent("ipt_searchWord").getValue() || ''));
        if ($c.util.getComponent('ipt_searchType').getValue() === "STD1") {
            scwin.comment.setStyle("display", "");
        } else {
            scwin.comment.setStyle("display", "none");
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90600.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_searchWord_onkeyup
 * @description ipt_searchWord 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_searchWord_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        fn_boardCheck(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90600.ipt_searchWord_onkeyup' }); }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description btn_Search 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf90600.btn_Search_onclick' }); }
};

/**
 * @method
 * @name grd_resultList_oncellclick
 * @description grd_resultList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resultList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.send_form(r["stdCd"], r["isuKorNm"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_window_onclick
 * @description btn_window 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90600.btn_window_onclick' }); }
};

/**
 * @method
 * @name btn_window_onfocus
 * @description btn_window 포커스 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onfocus = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.blur()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90600.btn_window_onfocus' }); }
};

/**
 * @method
 * @name __on_enter_1_ipt_searchword
 * @description on enter 1 ipt searchword 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_1_ipt_searchword = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.search() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf90600.__on_enter_1_ipt_searchWord' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/common/stdcd.do?method=",
        ref: "dma_SearchReq",
        target: "dlt_resultList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const search_type = $c.util.getComponent('dma_SearchReq').get('searchType');
    let method_val = "";
    if (search_type === "STD" || search_type === "STD1") {
        method_val = "objStkStdCd";
    }
    if (search_type === "BND") {
        method_val = "objTgtStdCd";
    }
    (document.JLDINF90600 || { elements: [] }).action = '/common/stdcd.do?method=' + method_val;
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name send_form
 * @description send form 처리
 * @param {*} std_cd std_cd
 * @param {*} com_nm com_nm
 * @returns {void}
 * @hidden N
 */
scwin.send_form = function (std_cd, com_nm) {
    const item_id = $c.util.getComponent('dma_SearchReq').get('itemId');
    const item_nm = $c.util.getComponent('dma_SearchReq').get('itemNm');
    (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById(item_id)) || { setValue: function () {} }).setValue(std_cd);
    (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById(item_nm)) || { setValue: function () {} }).setValue(com_nm);
    $c.win.closePopup();
};
